Projection.ArtifactTemplate:
{% for e in evidence %}- evidenceUri: {{ e.evidenceUri }} artifact memory
  uri: {{ e.slots.artifactUri }}
  status: {{ e.slots.status }}
  availableRefs: {{ e.slots.availableRefCount }}
  loadedRefs: {{ e.slots.memoryCount }}
  unavailableRefs: {{ e.slots.unavailableRefCount }}
  failedRefs: {{ e.slots.failedRefCount }}
  message: {{ e.slots.message }}
{% endfor %}

Summary.ArtifactTemplate:
{% for artifact in result.artifacts.item %}- sourceArtifactUri: {{ artifact.artifactUri }}
  status: {{ artifact.status }}
  loadedRefs: {{ artifact.memoryCount }}
  unavailableRefs: {{ artifact.unavailableRefCount }}
  failedRefs: {{ artifact.failedRefCount }}
{% for read in artifact.refResults.item %}  - ref={{ read.ref }} status={{ read.status }} message={{ read.message }}
{% endfor %}{% for memory in artifact.memories.item %}
## {{ memory.ref }} bytes={{ memory.range.startByte }}..{{ memory.range.endByte }}/{{ memory.range.totalBytes }} complete={{ memory.range.complete }}{% if memory.range.nextStartByte %} nextStartByte={{ memory.range.nextStartByte }}{% endif %}{% if memory.view %} jsonView kind={{ memory.view.kind }}{% if memory.view.rootType %} rootType={{ memory.view.rootType }} fields={{ memory.view.fieldCount }} startField={{ memory.view.startFieldIndex }} returnedFields={{ memory.view.returnedFieldCount }} remainingFields={{ memory.view.remainingFieldCount }} complete={{ memory.view.complete }}{% if memory.view.blockedAtFieldIndex %} blockedAtFieldIndex={{ memory.view.blockedAtFieldIndex }}{% endif %}{% else %} returned={{ memory.view.returned }} scanned={{ memory.view.scanned }} complete={{ memory.view.complete }}{% if memory.view.blockedAtIndex %} blockedAtIndex={{ memory.view.blockedAtIndex }}{% endif %}{% endif %}{% if memory.view.nextCursor %} nextCursor={{ memory.view.nextCursor }}{% endif %}{% endif %}
{{ memory.content }}
{% endfor %}{% endfor %}
